ALTER TABLE `PointTransaction` MODIFY `source` ENUM('MOCK_PAYMENT','VNPAY_IPN','MEMBER_REDEMPTION','MERCHANT_REFUND','MERCHANT_REWARD_CANCELLATION','ADMIN_ADJUSTMENT','LEGACY_BACKFILL','SYSTEM','CHALLENGE_REWARD','CHALLENGE_REFUND') NOT NULL DEFAULT 'LEGACY_BACKFILL';
CREATE TABLE `Challenge` (`id` INTEGER NOT NULL AUTO_INCREMENT,`merchantId` INTEGER NOT NULL,`title` VARCHAR(191) NOT NULL,`description` TEXT NOT NULL,`type` ENUM('ORDER_COUNT','DAILY_CHECKIN','SPEND_TOTAL') NOT NULL,`status` ENUM('DRAFT','ACTIVE','PAUSED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',`targetValue` DECIMAL(15,0) NOT NULL,`rewardPoints` DECIMAL(38,12) NOT NULL,`budgetTotal` DECIMAL(38,12) NOT NULL,`budgetSpent` DECIMAL(38,12) NOT NULL DEFAULT 0,`startsAt` DATETIME(3) NOT NULL,`endsAt` DATETIME(3) NOT NULL,`isFeatured` BOOLEAN NOT NULL DEFAULT false,`activatedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `Challenge_merchantId_status_startsAt_idx`(`merchantId`,`status`,`startsAt`),INDEX `Challenge_merchantId_type_idx`(`merchantId`,`type`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `MemberActivity` (`id` INTEGER NOT NULL AUTO_INCREMENT,`membershipId` INTEGER NOT NULL,`type` ENUM('ORDER_PAID','DAILY_CHECKIN','ORDER_REFUNDED') NOT NULL,`eventKey` VARCHAR(191) NOT NULL,`orderId` INTEGER NULL,`amountVnd` DECIMAL(15,0) NULL,`occurredAt` DATETIME(3) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE INDEX `MemberActivity_eventKey_key`(`eventKey`),INDEX `MemberActivity_membershipId_type_occurredAt_idx`(`membershipId`,`type`,`occurredAt`),INDEX `MemberActivity_orderId_idx`(`orderId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ChallengeProgress` (`id` INTEGER NOT NULL AUTO_INCREMENT,`challengeId` INTEGER NOT NULL,`membershipId` INTEGER NOT NULL,`currentValue` DECIMAL(15,0) NOT NULL DEFAULT 0,`rewardState` ENUM('IN_PROGRESS','WAITING_BUDGET','REWARDED') NOT NULL DEFAULT 'IN_PROGRESS',`rewardCycle` INTEGER NOT NULL DEFAULT 1,`completedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `ChallengeProgress_challengeId_membershipId_key`(`challengeId`,`membershipId`),INDEX `ChallengeProgress_challengeId_rewardState_completedAt_idx`(`challengeId`,`rewardState`,`completedAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ChallengeProgressEntry` (`id` INTEGER NOT NULL AUTO_INCREMENT,`progressId` INTEGER NOT NULL,`activityId` INTEGER NOT NULL,`deltaValue` DECIMAL(15,0) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE INDEX `ChallengeProgressEntry_progressId_activityId_key`(`progressId`,`activityId`),INDEX `ChallengeProgressEntry_activityId_idx`(`activityId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ChallengeRewardGrant` (`id` INTEGER NOT NULL AUTO_INCREMENT,`progressId` INTEGER NOT NULL,`cycle` INTEGER NOT NULL,`status` ENUM('GRANTED','REVERSED') NOT NULL DEFAULT 'GRANTED',`pointsGranted` DECIMAL(38,12) NOT NULL,`earnTransactionId` INTEGER NOT NULL,`reversalTransactionId` INTEGER NULL,`grantedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`reversedAt` DATETIME(3) NULL,UNIQUE INDEX `ChallengeRewardGrant_earnTransactionId_key`(`earnTransactionId`),UNIQUE INDEX `ChallengeRewardGrant_reversalTransactionId_key`(`reversalTransactionId`),UNIQUE INDEX `ChallengeRewardGrant_progressId_cycle_key`(`progressId`,`cycle`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `RefundRequest` (`id` INTEGER NOT NULL AUTO_INCREMENT,`orderId` INTEGER NOT NULL,`memberId` INTEGER NOT NULL,`merchantId` INTEGER NOT NULL,`reason` VARCHAR(255) NOT NULL,`status` ENUM('PENDING_MERCHANT','PENDING_ADMIN','REJECTED','APPROVED','PROCESSING','COMPLETED','FAILED') NOT NULL DEFAULT 'PENDING_MERCHANT',`requestedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`merchantReviewedById` INTEGER NULL,`merchantReviewedAt` DATETIME(3) NULL,`merchantDecisionReason` VARCHAR(255) NULL,`adminReviewedById` INTEGER NULL,`adminReviewedAt` DATETIME(3) NULL,`adminDecisionReason` VARCHAR(255) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `RefundRequest_orderId_key`(`orderId`),INDEX `RefundRequest_merchantId_status_requestedAt_idx`(`merchantId`,`status`,`requestedAt`),INDEX `RefundRequest_status_requestedAt_idx`(`status`,`requestedAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `Challenge` ADD CONSTRAINT `Challenge_merchantId_fkey` FOREIGN KEY (`merchantId`) REFERENCES `Merchant`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `MemberActivity` ADD CONSTRAINT `MemberActivity_membershipId_fkey` FOREIGN KEY (`membershipId`) REFERENCES `MerchantMembership`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `MemberActivity_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `Order`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `ChallengeProgress` ADD CONSTRAINT `ChallengeProgress_challengeId_fkey` FOREIGN KEY (`challengeId`) REFERENCES `Challenge`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `ChallengeProgress_membershipId_fkey` FOREIGN KEY (`membershipId`) REFERENCES `MerchantMembership`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `ChallengeProgressEntry` ADD CONSTRAINT `ChallengeProgressEntry_progressId_fkey` FOREIGN KEY (`progressId`) REFERENCES `ChallengeProgress`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `ChallengeProgressEntry_activityId_fkey` FOREIGN KEY (`activityId`) REFERENCES `MemberActivity`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `ChallengeRewardGrant` ADD CONSTRAINT `ChallengeRewardGrant_progressId_fkey` FOREIGN KEY (`progressId`) REFERENCES `ChallengeProgress`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `ChallengeRewardGrant_earnTransactionId_fkey` FOREIGN KEY (`earnTransactionId`) REFERENCES `PointTransaction`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `ChallengeRewardGrant_reversalTransactionId_fkey` FOREIGN KEY (`reversalTransactionId`) REFERENCES `PointTransaction`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `RefundRequest` ADD CONSTRAINT `RefundRequest_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `Order`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `RefundRequest_memberId_fkey` FOREIGN KEY (`memberId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `RefundRequest_merchantId_fkey` FOREIGN KEY (`merchantId`) REFERENCES `Merchant`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `RefundRequest_merchantReviewedById_fkey` FOREIGN KEY (`merchantReviewedById`) REFERENCES `User`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT `RefundRequest_adminReviewedById_fkey` FOREIGN KEY (`adminReviewedById`) REFERENCES `User`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
